import { z } from 'zod';
import { createLogger } from '../utils/logger';
import { renderRivetPage } from '../utils/rivetPage';
import { SIGN_IN_CALLBACK_COMPLETE_PATH } from '../types/rivet-page-types';
import { getConfigManager } from './ConfigManager';
import { createServer, IncomingMessage, ServerResponse } from 'http';
import { refreshAccessTokenViaProxy } from './accessTokenRefresh';
import {
  getRequestAuthContext,
  updateRequestAuthContext,
} from './RequestAuthContext';
import {
  clearPendingLogin,
  readPendingLogin,
  writePendingLogin,
  type PendingLogin,
} from './pendingLogin';
import { errorMessage } from '../utils/errorMessage';
import { resolveProxyDashboardUrl } from '../config/proxy';

const log = createLogger('AuthService');
const LOOPBACK_HOST = '127.0.0.1';
const LOOPBACK_PORT = 0;
const OAUTH_CALLBACK_TIMEOUT_MS = 120_000;
const MAX_CALLBACK_BODY_BYTES = 64 * 1024;
const PROFILE_FETCH_TIMEOUT_MS = 10_000;

export type LoginSource = 'cli' | 'mcp' | 'core';

export type GoogleLoginOptions = {
  redirectOrigin?: string;
  authDestination?: string;
  source?: LoginSource;
  editor?: string;
  version?: string;
  noBrowser?: boolean;
  onAuthUrl?: (url: string) => void;
};

const LoginResponseSchema = z.object({
  success: z.boolean(),
  token: z.string().optional(),
  refreshToken: z.string().optional(),
  user: z
    .object({
      id: z.string(),
      email: z.string(),
      displayName: z.string().optional(),
    })
    .optional(),
  profile: z
    .object({
      remaining_spend_usd: z.number().nullish(),
      monthly_limit_usd: z.number().nullish(),
      current_month_spend_usd: z.number().nullish(),
      total_spend_usd: z.number().nullish(),
    })
    .nullish(),
  error: z.string().optional(),
  message: z.string().optional(),
});

type LoginResponse = z.infer<typeof LoginResponseSchema>;

type UserProfile = {
  user: {
    id: string;
    email: string;
    displayName?: string;
  };
  profile: {
    remaining_spend_usd: number;
    monthly_limit_usd: number;
    current_month_spend_usd: number;
    total_spend_usd: number;
    created_at: string;
  };
};

type OAuthCallbackTokens = {
  sessionId: string;
  accessToken: string;
  refreshToken?: string;
};

const GoogleOAuthStartResultSchema = z.object({
  success: z.boolean(),
  authUrl: z.string().optional(),
  sessionId: z.string().optional(),
  pollSecret: z.string().optional(),
  completionSecret: z.string().optional(),
  flow: z.string().optional(),
  error: z.string().optional(),
  message: z.string().optional(),
});

type GoogleOAuthStartResult = z.infer<typeof GoogleOAuthStartResultSchema>;

type GoogleOAuthStartRequest = GoogleLoginOptions & {
  flow?: 'pkce';
  installRef?: string;
};

type LoopbackOAuthCallback = {
  redirectOrigin: string;
  waitForTokens: Promise<OAuthCallbackTokens>;
  close: () => Promise<void>;
};

type LocalAuthBridgeProfile = {
  email: string;
  userId: string;
};

type LogoutOptions = {
  token?: string;
  shouldClearLocalAuth?: boolean;
};

const sendTextResponse = (
  response: ServerResponse,
  statusCode: number,
  body: string,
): void => {
  response.statusCode = statusCode;
  response.setHeader('Content-Type', 'text/html; charset=utf-8');
  response.end(body);
};

const readRequestBody = (request: IncomingMessage): Promise<string> => {
  return new Promise((resolve, reject) => {
    let body = '';
    request.on('data', (chunk: Buffer) => {
      body += chunk.toString('utf8');
      if (Buffer.byteLength(body) > MAX_CALLBACK_BODY_BYTES) {
        reject(new Error('OAuth callback payload too large'));
        request.destroy();
      }
    });
    request.on('end', () => resolve(body));
    request.on('error', reject);
  });
};

export const validateAccessToken = async (
  proxyUrl: string,
  accessToken: string,
): Promise<LocalAuthBridgeProfile | null> => {
  const response = await fetch(
    `${proxyUrl.replace(/\/$/, '')}/api/user/profile`,
    {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${accessToken}`,
      },
      signal: AbortSignal.timeout(PROFILE_FETCH_TIMEOUT_MS),
    },
  );
  const result = z
    .object({
      success: z.literal(true),
      user: z.object({ id: z.string(), email: z.string() }),
    })
    .safeParse(await response.json().catch(() => null));

  if (!response.ok || !result.success) {
    return null;
  }

  return {
    email: result.data.user.email,
    userId: result.data.user.id,
  };
};

const createLoopbackOAuthCallback =
  async (): Promise<LoopbackOAuthCallback> => {
    let resolveTokens: (tokens: OAuthCallbackTokens) => void = () => {};
    let rejectTokens: (error: Error) => void = () => {};
    let timeout: NodeJS.Timeout | null = null;
    const clearCallbackTimeout = () => {
      if (timeout) {
        clearTimeout(timeout);
        timeout = null;
      }
    };

    const waitForTokens = new Promise<OAuthCallbackTokens>(
      (resolve, reject) => {
        resolveTokens = resolve;
        rejectTokens = reject;
        timeout = setTimeout(() => {
          timeout = null;
          reject(new Error('OAuth callback timed out'));
        }, OAUTH_CALLBACK_TIMEOUT_MS);
      },
    );

    const server = createServer((request, response) => {
      const url = new URL(request.url ?? '/', `http://${LOOPBACK_HOST}`);

      if (request.method === 'GET') {
        sendTextResponse(
          response,
          200,
          renderRivetPage({
            page: { kind: 'sign-in-callback' },
            head: { title: 'Rivet authentication' },
          }),
        );
        return;
      }

      if (
        request.method !== 'POST' ||
        url.pathname !== SIGN_IN_CALLBACK_COMPLETE_PATH
      ) {
        sendTextResponse(response, 404, 'Not found');
        return;
      }

      void readRequestBody(request)
        .then((body) => {
          const payload = JSON.parse(body) as Partial<OAuthCallbackTokens>;
          if (!payload.sessionId || !payload.accessToken) {
            throw new Error('OAuth callback missing session or token');
          }
          clearCallbackTimeout();
          resolveTokens({
            sessionId: payload.sessionId,
            accessToken: payload.accessToken,
            refreshToken: payload.refreshToken,
          });
          sendTextResponse(response, 200, 'Authentication complete');
        })
        .catch((error) => {
          clearCallbackTimeout();
          rejectTokens(
            error instanceof Error ? error : new Error(String(error)),
          );
          sendTextResponse(response, 400, 'Authentication failed');
        });
    });

    await new Promise<void>((resolve) => {
      server.listen(LOOPBACK_PORT, LOOPBACK_HOST, () => resolve());
    });

    const address = server.address();
    if (!address || typeof address === 'string') {
      throw new Error('Unable to start OAuth callback server');
    }

    return {
      redirectOrigin: `http://${LOOPBACK_HOST}:${address.port}`,
      waitForTokens,
      close: () =>
        new Promise<void>((resolve) => {
          clearCallbackTimeout();
          server.close(() => resolve());
        }),
    };
  };

export class AuthService {
  private proxyUrl: string;
  private configManager = getConfigManager();

  constructor(proxyUrl?: string) {
    this.proxyUrl = proxyUrl || this.configManager.getProxyUrl();
    log.debug(`AuthService initialized with proxy URL: ${this.proxyUrl}`);
  }

  async loginWithEmailPassword(
    email: string,
    password: string,
  ): Promise<LoginResponse> {
    try {
      const expectedGeneration = this.configManager.beginSignIn();
      const response = await fetch(`${this.proxyUrl}/api/auth/email/signin`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email.trim().toLowerCase(), password }),
      });

      if (!response.ok) {
        const text = await response.text();
        log.warn(`Email sign-in failed with status ${response.status}:`, text);
        return {
          success: false,
          error: `HTTP ${response.status}`,
          message: text.substring(0, 200),
        };
      }

      const parsed = LoginResponseSchema.safeParse(await response.json());
      if (!parsed.success) {
        return { success: false, error: 'Invalid sign-in response' };
      }
      const result = parsed.data;
      if (!result.success) {
        return {
          success: false,
          error: result.error ?? 'Email sign-in failed',
          message: result.message,
        };
      }
      if (result.token && result.user?.email) {
        this.configManager.setAuth(
          result.token,
          result.user.email,
          result.refreshToken,
          result.user.id,
          { expectedGeneration, isRecovery: true },
        );
        log.info(`Signed in as ${result.user.email} (CI)`);
      }
      return result;
    } catch (error) {
      log.warn('Email sign-in error:', error);
      return {
        success: false,
        error: 'Network error',
        message: errorMessage(error, 'Unknown error occurred'),
      };
    }
  }

  async loginWithGoogle(
    optionsOrRedirectOrigin?: string | GoogleLoginOptions,
  ): Promise<LoginResponse> {
    const options: GoogleLoginOptions =
      typeof optionsOrRedirectOrigin === 'string'
        ? { redirectOrigin: optionsOrRedirectOrigin }
        : (optionsOrRedirectOrigin ?? {});
    const installRef = this.configManager.getInstallRef();
    const requestOptions: GoogleOAuthStartRequest = { ...options, installRef };
    let loopbackCallback: LoopbackOAuthCallback | null = null;
    try {
      const expectedGeneration = this.configManager.beginSignIn();
      let startResult = !requestOptions.redirectOrigin
        ? await this.startGoogleOAuth({ ...requestOptions, flow: 'pkce' })
        : null;

      if (!startResult || startResult.flow !== 'pkce') {
        if (requestOptions.source === 'mcp' && !requestOptions.redirectOrigin) {
          loopbackCallback = await createLoopbackOAuthCallback();
          requestOptions.redirectOrigin = loopbackCallback.redirectOrigin;
        }
        startResult = await this.startGoogleOAuth(requestOptions);
      }

      if (!startResult) {
        return {
          success: false,
          error: 'Failed to start authentication',
          message: 'Could not start the Google sign-in flow.',
        };
      }
      if (!startResult.success) {
        return {
          success: false,
          error: startResult.error || 'Failed to start authentication',
          message: startResult.message,
        };
      }

      const authUrl = startResult.authUrl;
      const sessionId = startResult.sessionId;
      const pollSecret = startResult.pollSecret;
      const completionSecret = startResult.completionSecret;
      if (!authUrl || !sessionId || !pollSecret) {
        return {
          success: false,
          error: 'Invalid response from server',
          message: 'Authentication response missing session or poll secret',
        };
      }

      if (startResult.flow === 'pkce') {
        writePendingLogin({
          sessionId,
          pollSecret,
          proxyUrl: this.proxyUrl,
          createdAt: Date.now(),
          generation: expectedGeneration,
          authUrl,
          ...(installRef ? { installRef } : {}),
        });
      }

      options.onAuthUrl?.(authUrl);
      if (!options.noBrowser) {
        try {
          const open = (await import('open')).default;
          await open(authUrl);
          log.info('Opened browser for Google authentication');
        } catch (error) {
          log.warn('Could not open browser for login:', error);
        }
      }
      log.info('Waiting for authentication...');

      if (loopbackCallback) {
        if (!completionSecret) {
          return {
            success: false,
            error: 'Invalid response from server',
            message: 'Authentication response missing completion secret',
          };
        }

        const callbackTokens = await loopbackCallback.waitForTokens;
        if (callbackTokens.sessionId !== sessionId) {
          return {
            success: false,
            error: 'Invalid OAuth callback',
            message: 'OAuth callback session did not match login session',
          };
        }

        const completeResponse = await fetch(
          `${this.proxyUrl}/api/auth/google/complete`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              ...callbackTokens,
              completionSecret,
            }),
          },
        );
        const completeResult = await completeResponse.json();
        if (!completeResponse.ok || !completeResult.success) {
          return {
            success: false,
            error: completeResult.error || 'Authentication failed',
            message: completeResult.message,
          };
        }
      }

      const tokenResult = await this.pollForToken(
        sessionId,
        pollSecret,
        startResult.flow === 'pkce' ? 150 : 60,
      );

      if (tokenResult.success && tokenResult.token && tokenResult.user) {
        this.configManager.setAuth(
          tokenResult.token,
          tokenResult.user.email,
          tokenResult.refreshToken,
          tokenResult.user.id,
          { expectedGeneration, isRecovery: true },
        );
        if (installRef) {
          this.configManager.completeInstallRefSignIn(
            installRef,
            tokenResult.user.id,
          );
        }
        log.info(`Logged in as ${tokenResult.user.email}`);
      }
      if (startResult.flow === 'pkce') {
        if (tokenResult.success || tokenResult.error !== 'Timeout') {
          clearPendingLogin();
        }
      }

      return tokenResult;
    } catch (error) {
      log.warn('Google login error:', error);
      return {
        success: false,
        error: 'Network error',
        message: errorMessage(error, 'Unknown error occurred'),
      };
    } finally {
      await loopbackCallback?.close();
    }
  }

  private async startGoogleOAuth(
    requestOptions: GoogleOAuthStartRequest,
  ): Promise<GoogleOAuthStartResult | null> {
    log.info(
      `Requesting OAuth URL from: ${this.proxyUrl}/api/auth/google/start`,
    );

    const body: {
      redirectOrigin?: string;
      authDestination?: string;
      source?: LoginSource;
      editor?: string;
      version?: string;
      flow?: string;
      ref?: string;
    } = {};
    if (requestOptions.redirectOrigin) {
      body.redirectOrigin = requestOptions.redirectOrigin;
    }
    body.authDestination =
      requestOptions.authDestination ?? resolveProxyDashboardUrl(this.proxyUrl);
    if (requestOptions.source) {
      body.source = requestOptions.source;
    }
    if (requestOptions.editor) {
      body.editor = requestOptions.editor;
    }
    if (requestOptions.version) {
      body.version = requestOptions.version;
    }
    if (requestOptions.flow) {
      body.flow = requestOptions.flow;
    }
    if (requestOptions.installRef) {
      body.ref = requestOptions.installRef;
    }

    try {
      const response = await fetch(`${this.proxyUrl}/api/auth/google/start`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const result = GoogleOAuthStartResultSchema.parse(await response.json());
      if (!response.ok || !result.success) {
        log.warn('Failed to start Google OAuth:', result.error, result.message);
        return { ...result, success: false };
      }
      return result;
    } catch (error) {
      log.warn('Error starting Google OAuth:', error);
      return null;
    }
  }

  async beginGoogleLogin(
    options: GoogleLoginOptions = {},
  ): Promise<
    | { started: true; authUrl: string; sessionId: string }
    | { started: false; error: string }
  > {
    const installRef = this.configManager.getInstallRef();
    const expectedGeneration = this.configManager.beginSignIn();
    const startResult = await this.startGoogleOAuth({
      ...options,
      flow: 'pkce',
      installRef,
    });
    if (!startResult || !startResult.success) {
      return {
        started: false,
        error:
          startResult?.message ||
          startResult?.error ||
          'Could not reach the sign-in service.',
      };
    }
    if (
      startResult.flow !== 'pkce' ||
      !startResult.sessionId ||
      !startResult.pollSecret ||
      !startResult.authUrl
    ) {
      return {
        started: false,
        error:
          'The sign-in service does not support detached login yet. Run `rivet login` in a terminal instead.',
      };
    }

    writePendingLogin({
      sessionId: startResult.sessionId,
      pollSecret: startResult.pollSecret,
      proxyUrl: this.proxyUrl,
      createdAt: Date.now(),
      generation: expectedGeneration,
      authUrl: startResult.authUrl,
      ...(installRef ? { installRef } : {}),
    });

    if (!options.noBrowser) {
      try {
        const open = (await import('open')).default;
        await open(startResult.authUrl);
      } catch (error) {
        log.warn('Could not open browser for login:', error);
      }
    }

    return {
      started: true,
      authUrl: startResult.authUrl,
      sessionId: startResult.sessionId,
    };
  }

  peekPendingLogin(): PendingLogin | null {
    const pending = readPendingLogin();
    return pending && pending.proxyUrl === this.proxyUrl ? pending : null;
  }

  async resumePendingLogin(maxAttempts = 1): Promise<LoginResponse | null> {
    const pending = this.peekPendingLogin();
    if (!pending) {
      return null;
    }

    const tokenResult = await this.pollForToken(
      pending.sessionId,
      pending.pollSecret,
      maxAttempts,
    );

    if (tokenResult.success && tokenResult.token && tokenResult.user) {
      clearPendingLogin();
      this.configManager.setAuth(
        tokenResult.token,
        tokenResult.user.email,
        tokenResult.refreshToken,
        tokenResult.user.id,
        { expectedGeneration: pending.generation, isRecovery: true },
      );
      if (pending.installRef) {
        this.configManager.completeInstallRefSignIn(
          pending.installRef,
          tokenResult.user.id,
        );
      }
      log.info(`Logged in as ${tokenResult.user.email} (resumed login)`);
      return tokenResult;
    }

    if (tokenResult.error && tokenResult.error !== 'Timeout') {
      clearPendingLogin();
      return tokenResult;
    }

    return null;
  }

  private async pollForToken(
    sessionId: string,
    pollSecret: string,
    maxAttempts: number = 60,
  ): Promise<LoginResponse> {
    for (let i = 0; i < maxAttempts; i++) {
      try {
        const response = await fetch(`${this.proxyUrl}/api/auth/google/token`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            session: sessionId,
            pollSecret,
          }),
        });

        const parsed = LoginResponseSchema.safeParse(await response.json());
        if (!parsed.success) {
          return { success: false, error: 'Invalid token response' };
        }
        const result = parsed.data;

        if (result.success) {
          return result;
        }

        if (result.error && result.error !== 'Pending') {
          return result;
        }

        if (i < maxAttempts - 1) {
          await new Promise((resolve) => setTimeout(resolve, 2000));
        }
      } catch (error) {
        log.warn('Error polling for token:', error);
      }
    }

    const waitedMinutes = Math.max(
      1,
      Math.round((maxAttempts * 2000) / 60_000),
    );
    return {
      success: false,
      error: 'Timeout',
      message: `Authentication timed out after ${waitedMinutes} minute${waitedMinutes === 1 ? '' : 's'}`,
    };
  }

  async logout(options: LogoutOptions = {}): Promise<void> {
    const token = options.token ?? this.configManager.getAuthToken();
    const shouldClearLocalAuth = options.shouldClearLocalAuth ?? true;

    if (token) {
      try {
        await fetch(`${this.proxyUrl}/api/auth/logout`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
        });
      } catch (error) {
        log.warn('Logout error:', error);
      }
    }

    if (shouldClearLocalAuth) {
      this.configManager.clearAuth();
    }
    log.info('Logged out successfully');
  }

  async ensureAuthenticated(): Promise<boolean> {
    const profile = await this.getValidatedProfile();
    return profile !== null;
  }

  async getValidatedProfile(): Promise<UserProfile | null> {
    const fetchProfile = async (
      bearer: string,
    ): Promise<{ status: number; profile: UserProfile | null }> => {
      const response = await fetch(`${this.proxyUrl}/api/user/profile`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${bearer}`,
        },
        signal: AbortSignal.timeout(PROFILE_FETCH_TIMEOUT_MS),
      });
      if (!response.ok) {
        return { status: response.status, profile: null };
      }
      const result = await response.json().catch(() => null);
      return {
        status: response.status,
        profile: result?.success ? (result as UserProfile) : null,
      };
    };

    try {
      const requestContext = getRequestAuthContext();
      const expectedGeneration = requestContext
        ? undefined
        : this.configManager.getAuthorizationGeneration();
      const capturedEmail = this.configManager.getEmail() || '';
      const capturedUserId = this.configManager.getUserId();
      const capturedRefreshToken =
        requestContext?.refreshToken ?? this.configManager.getRefreshToken();
      const token = requestContext?.token ?? this.configManager.getAuthToken();
      if (!token) {
        return null;
      }
      const first = await fetchProfile(token);
      if (first.profile) {
        return first.profile;
      }
      if (first.status !== 401) {
        return null;
      }

      const refreshToken = capturedRefreshToken;
      if (!refreshToken) {
        return null;
      }
      const refreshed = await refreshAccessTokenViaProxy({
        refreshToken,
        proxyUrl: this.proxyUrl,
      });
      if (!refreshed) {
        return null;
      }
      const retry = await fetchProfile(refreshed.token);
      if (retry.profile?.user) {
        if (requestContext) {
          updateRequestAuthContext({
            token: refreshed.token,
            refreshToken: refreshed.refreshToken,
            email: retry.profile.user.email,
            userId: retry.profile.user.id,
          });
        } else {
          this.configManager.setAuth(
            refreshed.token,
            retry.profile.user.email,
            refreshed.refreshToken,
            retry.profile.user.id,
            { expectedGeneration },
          );
        }
      } else {
        const email = capturedEmail;
        const userId = capturedUserId;
        if (requestContext) {
          updateRequestAuthContext({
            token: refreshed.token,
            refreshToken: refreshed.refreshToken,
            email,
            userId,
          });
        } else {
          this.configManager.setAuth(
            refreshed.token,
            email,
            refreshed.refreshToken,
            userId,
            { expectedGeneration },
          );
        }
      }
      return retry.profile;
    } catch (error) {
      log.warn('Validated profile fetch error:', error);
      return null;
    }
  }

  isAuthenticated(): boolean {
    return this.configManager.isAuthenticated();
  }

  getAuthToken(): string | undefined {
    return this.configManager.getAuthToken();
  }
}
